// Emits lib/aie/vendor-directory.ts from the live vendor fixture.
//
// Why a generated file rather than a read at runtime. Three client components
// need a vendor's name and score (the market-watch share chart, and both news
// feeds), and a module that reads the filesystem cannot be imported into a
// client bundle: webpack fails on node:fs. Importing the 92KB fixture as JSON
// would work but ships all of it to the browser for a name lookup.
//
// So the small part is generated: 47 vendors, id, name, category and the three
// published scores. Plain TypeScript, no imports, safe on either side of the
// boundary, and regenerated by the sync so it cannot drift the way the July
// port did.
//
// Usage:  node scripts/generate-vendor-directory.mjs

import { readFileSync, writeFileSync } from "node:fs";

const raw = JSON.parse(readFileSync("fixtures/aie-live/vendors.json", "utf8"));
// vendors.json carries no capture stamp of its own, so the freshest
// lastUpdated across the roster is used. Better an understated date from the
// data than a clock reading that claims a freshness the source never gave.
const asOf =
  raw.asOf ??
  ((raw.vendors ?? [])
    .map((v) => v.lastUpdated)
    .filter((d) => typeof d === "string")
    .sort()
    .pop() ?? null);
const rows = (raw.vendors ?? [])
  .map((v) => ({
    id: String(v.id),
    name: String(v.name ?? v.id),
    category: v.category ?? null,
    ownershipType: v.ownershipType ?? null,
    overallScore: typeof v.overallScore === "number" ? v.overallScore : null,
    confidenceScore:
      typeof v.confidenceScore === "number" ? v.confidenceScore : null,
    marketPosition: v.marketPosition ?? null,
  }))
  .sort((a, b) => a.id.localeCompare(b.id));

const header = `// GENERATED by scripts/generate-vendor-directory.mjs. Do not edit by hand.
//
// The vendor roster and its published scores, taken from the live AI Enterprise
// source (fixtures/aie-live/vendors.json, captured ${asOf ?? "unknown"}).
//
// This exists so a client component can look up a vendor's name or score
// without pulling node:fs into the browser bundle. It replaces the name and
// roster lookups that used to come from lib/aie/intelligence/entities.ts, a
// copy of the same source frozen on 8 July 2026 which had drifted far enough
// that every one of 37 overlapping vendors scored higher in it than upstream,
// by 18 points on average.
//
// Regenerate after every sync. If this file is stale the whole product is.

export interface DirectoryVendor {
  id: string;
  name: string;
  category: string | null;
  ownershipType: string | null;
  overallScore: number | null;
  confidenceScore: number | null;
  marketPosition: string | null;
}

/** The capture these figures came from. */
export const VENDOR_DIRECTORY_AS_OF = ${JSON.stringify(asOf)};

`;

const body = `export const VENDOR_DIRECTORY: DirectoryVendor[] = ${JSON.stringify(rows, null, 2)};

const BY_ID = new Map(VENDOR_DIRECTORY.map((v) => [v.id, v]));

// The July port renamed five vendors, so any join on id silently dropped them.
// Kept here as well as in live-vendors.ts because this module has to work in
// the browser, where that one cannot go.
const ALIASES: Record<string, string> = {
  "alibaba-qwen": "alibaba",
  "fireworks-ai": "fireworks",
  "moonshot-kimi": "moonshot",
  "together-ai": "together",
  "zhipu-glm": "zai",
};

export function directoryVendor(id: string): DirectoryVendor | null {
  return BY_ID.get(ALIASES[id] ?? id) ?? null;
}

/** A vendor's published name, falling back to the id rather than to blank. */
export function vendorName(id: string): string {
  return directoryVendor(id)?.name ?? id;
}
`;

writeFileSync("lib/aie/vendor-directory.ts", header + body);
console.log(
  `wrote lib/aie/vendor-directory.ts: ${rows.length} vendors, captured ${asOf}`
);
